MStatus SpringChain::compute(const MPlug& plug, MDataBlock& data) {
    if (plug != aDriven)
        return MS::kUnknownParameter;

    // --- inputs ---
    const float in_aDamping = data.inputValue(aDamping).asFloat();
    const double3& in_aDriver = data.inputValue(aDriver).asDouble3();
    const double3& in_aGravity = data.inputValue(aGravity).asDouble3();
    const float in_aMass = data.inputValue(aMass).asFloat();
    const float in_aMaxDistance = data.inputValue(aMaxDistance).asFloat();
    const float in_aMinDistance = data.inputValue(aMinDistance).asFloat();
    const short in_aResetBuffer = data.inputValue(aResetBuffer).asShort();
    const float in_aTension = data.inputValue(aTension).asFloat();
    const double in_aTime = data.inputValue(aTime).asTime().value();

    // ===== BEGIN PORTED COMPUTE =====
        NodeState* st = &_state;

        (void)in_aTime;   // time only dirties driven every frame; the Python never reads it

        // len(self.driven): the element count of the driven output array.
        MArrayDataHandle _outArr = data.outputArrayValue(aDriven);
        const size_t n = _outArr.elementCount();

        // Output writer, fused into the chain loop so the API calls overlap the
        // chain's serial divide/sqrt latency. It writes the multi IN PLACE when
        // its elements are exactly logical 0..n-1 (every tick after the first):
        // array elements are kept sorted by logical index, so n unique indices
        // whose first is 0 and last is n-1 are exactly 0..n-1. Any other layout
        // skips this and the builder below rewrites the whole multi.
        bool     _inPlace = n > 0;
        bool     _cleanedEarly = false;   // data.setClean(aDriven) already issued
        unsigned _nOut    = 0;
        if (_inPlace)
            _inPlace = _outArr.jumpToArrayElement((unsigned)n - 1) == MS::kSuccess
                    && _outArr.elementIndex() == (unsigned)n - 1
                    && _outArr.jumpToArrayElement(0) == MS::kSuccess
                    && _outArr.elementIndex() == 0;
        auto emit = [&](double x, double y, double z) {
            if (_inPlace) {
                // Store straight into the element's double3 (one call fewer
                // than set3Double); the handle stays alive while r is used.
                MDataHandle h = _outArr.outputValue();
                double3&    r = h.asDouble3();
                r[0] = x; r[1] = y; r[2] = z;
                _outArr.next();
                ++_nOut;
            }
        };
        const MVector zero(0.0, 0.0, 0.0);   // np.zeros(3)

        // spring() from the Init tab. The Python returns the new (p1, v); here p1
        // and v are updated in place. The components stay independent until the
        // norm, so one pass per component reproduces numpy's element-wise ops.
        // Each product gets its own statement: clang's default -ffp-contract=on
        // only fuses a multiply-add inside one expression, and numpy rounds every
        // element-wise op separately.
        auto spring = [](const double qx, const double qy, const double qz,
                         double& px, double& py, double& pz,
                         double& wx, double& wy, double& wz,
                         const double gx, const double gy, const double gz,
                         double k, double m, double d, double minDist, double maxDist) {
            spring_step(qx, qy, qz, px, py, pz, wx, wy, wz, gx, gy, gz, k, m, d, minDist, maxDist);
        };

        // Fresh (vanilla) node: seed the spring buffers so the first integration
        // has state.
        // ND_PORT_INCOMPLETE: the Python node restores self.position / self.velocity from the saved scene (mPyNode stored vars); this region can add no storable attribute and may do no file I/O, so the buffers are session-only and a reopened scene restarts the chain from zero (the vanilla seed below) instead of from its saved state.
        if (!st->buffers_isset) {
            st->velocity.assign(n, zero);
            st->position.assign(n, zero);
            st->buffers_isset = true;
        }

        bool integrated = false;
        if (!st->initialized) {
            // First eval: just latch initialized and push the stored buffer out.
            st->initialized = true;
        } else if (in_aResetBuffer != 0) {
            st->velocity.assign(n, zero);
            st->position.assign(n, zero);
        } else if (st->velocity.size() < n) {
            st->velocity.resize(n, zero);
            st->position.resize(n, zero);
        } else if (st->velocity.size() > n) {
            st->velocity.resize(n);
            st->position.resize(n);
        } else if (n > 0) {   // n == 0: the Python raises IndexError on self.position[0]
            const MVector driver(in_aDriver[0], in_aDriver[1], in_aDriver[2]);
            const MVector gravity(in_aGravity[0], in_aGravity[1], in_aGravity[2]);
            const double k       = (double)in_aTension;
            const double m       = (double)in_aMass;
            const double d       = (double)in_aDamping;
            const double minDist = (double)in_aMinDistance;
            const double maxDist = (double)in_aMaxDistance;

            MVector* P = st->position.data();
            MVector* V = st->velocity.data();

            // Initial drag (p0 = driver), then spring forces down the chain:
            // p0 of link i is link i - 1's position from THIS eval, carried in
            // qx/qy/qz so the serial chain never round-trips through memory.
            const double gx = gravity.x, gy = gravity.y, gz = gravity.z;
            ChainJob j;
            j.P = P; j.V = V; j.n = n;
            j.qx = driver.x; j.qy = driver.y; j.qz = driver.z;
            j.gx = gx; j.gy = gy; j.gz = gz;
            j.k = k; j.m = m; j.d = d; j.minDist = minDist; j.maxDist = maxDist;
            if (_inPlace && n >= kOffloadMinLinks && _worker.enabled() && _worker.start(j)) {
                // The chain runs on the node's worker while this thread hands
                // Maya the attribute-level clean -- the two costs overlap. The
                // values then go out in place, chunk by chunk, as they finish.
                data.setClean(aDriven);
                _cleanedEarly = true;
                // Write each finished chunk while the worker integrates the
                // rest; returns only once all n links are integrated.
                for (size_t i = 0; i < n;) {
                    const size_t e = _worker.waitFor(i + 1);
                    for (; i < e; ++i)
                        emit(P[i].x, P[i].y, P[i].z);
                }
            } else {
                // Small chain, no worker, or a rebuilt multi: integrate here,
                // fused with the in-place writer.
                double qx = driver.x, qy = driver.y, qz = driver.z;
                for (size_t i = 0; i < n; ++i) {
                    double px = P[i].x, py = P[i].y, pz = P[i].z;
                    double wx = V[i].x, wy = V[i].y, wz = V[i].z;
                    spring(qx, qy, qz, px, py, pz, wx, wy, wz, gx, gy, gz, k, m, d, minDist, maxDist);
                    P[i].x = px; P[i].y = py; P[i].z = pz;
                    V[i].x = wx; V[i].y = wy; V[i].z = wz;
                    emit(px, py, pz);
                    qx = px; qy = py; qz = pz;
                }
            }
            integrated = true;
        }

        // Output positions from the stored buffer
        const std::vector<MVector>& pos = st->position;
        if (!integrated)
            for (size_t i = 0; i < pos.size() && _inPlace; ++i)
                emit(pos[i].x, pos[i].y, pos[i].z);
    // ===== END PORTED COMPUTE =====

    // --- finalize ---
    {
        // Done in place only if every element went out and the count matched;
        // otherwise the builder rewrites the whole multi, as it always did.
        const bool _done = _inPlace && _nOut == pos.size() && pos.size() == n;
        if (!_done && !pos.empty()) {
            const std::vector<MVector>& out_aDriven = pos;
            MArrayDataBuilder _b(&data, aDriven, (unsigned)out_aDriven.size());
            for (size_t _i = 0; _i < out_aDriven.size(); ++_i) {
                MDataHandle eh = _b.addElement((unsigned)_i);
                eh.set3Double((out_aDriven[_i]).x, (out_aDriven[_i]).y, (out_aDriven[_i]).z);
            }
            _outArr.set(_b);
        } else if (!_done) {
            MVector _dflt = MVector();
            unsigned _ne = _outArr.elementCount();
            for (unsigned _i = 0; _i < _ne; ++_i) {
                MDataHandle eh = _outArr.outputValue();
                eh.set3Double((_dflt).x, (_dflt).y, (_dflt).z);
                _outArr.next();
            }
        }
        _outArr.setAllClean();
        if (!_cleanedEarly)
            data.setClean(aDriven);
    }

    return MS::kSuccess;
}

